"""Generate assets/dark.css from assets/minimal.css by remapping light colours to a dark palette.
Run: python3 _src/mkdark.py   (dark only applies when <html data-theme="dark">, chosen by the user)."""
import re,sys,os
here=os.path.dirname(os.path.abspath(__file__)); root=os.path.dirname(here)
def load(f): return re.sub(r'/\*.*?\*/','',open(os.path.join(root,'assets/'+f)).read(),flags=re.S)
SURF='#292a2d'; SOFT='#35363a'; LINE='#3c4043'; INK='#e8eaed'; MUT='#9aa0a6'
BG={ '#fff':SURF,'#ffffff':SURF,'#f4f6fb':SOFT,'#f6f1fc':SOFT,'#eef2f8':SOFT,'#f1f3f8':SOFT,'#f1ebfa':'#2b3350','#e9ecf2':SOFT,'#f7f8fb':'#1f2023','#eceef4':'#151618',
 '#d9d9d9':'#44464a','#a6a6a6':'#5a5d62','#ede5f8':'#27384f','#cdb8ee':'#46618c','#fff8e1':'#3a3320','#fdf0c4':'#3a3320','#fff6d6':'#3a3320','#f1e0a8':'#5a4d25','#e4cf93':'#5a4d25',
 '#ede5f8':'#392c63','#d8c8f0':'#4a3a85','#e8f8ee':'#1f3a2a','#ffe1e2':'#4a2427','#d3c0f2':'#d3c0f2','#e4e8f0':LINE,'#e3e5ea':LINE,'#cfd6e4':LINE}
FG={'#1c2230':INK,'#1a1917':INK,'#111':INK,'#2b3142':INK,'#394150':INK,'#2b3342':INK,'#444b5c':'#c4c7cc','#667085':MUT,'#5a6275':MUT,'#8a93a6':MUT,'#9aa1ae':MUT,'#4038a8':'#c8b2f0','#4a2d8a':'#c8b2f0','#177a3c':'#7fd49a','#000':INK,'#000000':INK,'#333':'#c4c7cc','#444':'#c4c7cc','#858a94':MUT,'#9a9a9a':MUT,'#b00020':'#ff8a80'}
BORD=dict(BG); BORD.update({'#000':'#5f6368','#000000':'#5f6368','#111':'#5f6368'})
def mp(val,table):
    def f(m):
        h=m.group(0).lower()
        return table.get(h,m.group(0))
    return re.sub(r'#[0-9a-fA-F]{3,6}\b',f,val)
BGP=re.compile(r'^(background|background-color|background-image|border|border-top|border-bottom|border-left|border-right|border-color|outline|border-top-color|border-bottom-color)$')
TEXT_ONLY=False
def conv(decls):
    out=[]
    for d in decls:
        if ':' not in d: continue
        k,v=d.split(':',1); k=k.strip(); v=v.strip().replace('!important','').strip()
        if TEXT_ONLY and k not in('color','fill','stroke'): continue
        if k=='background' or k=='background-color' or k=='background-image': nv=mp(v,BG)
        elif BGP.match(k): nv=mp(v,BORD)
        elif k in('color','fill','stroke'): nv=mp(v,FG)
        else: continue
        if nv!=v: out.append('%s:%s!important'%(k,nv))
    return out
def pre(sel):
    r=[]
    for s in sel.split(','):
        s=s.strip()
        if not s: continue
        if s.startswith('html'): r.append('html[data-theme="dark"]'+s[4:])
        elif s.startswith(':root'): continue
        else: r.append('html[data-theme="dark"] '+s)
    return ','.join(r)
def walk(text):
    res=[]; i=0
    while i<len(text):
        j=text.find('{',i)
        if j<0: break
        head=text[i:j].strip()
        # find matching brace
        d=1;k=j+1
        while k<len(text) and d:
            if text[k]=='{': d+=1
            elif text[k]=='}': d-=1
            k+=1
        body=text[j+1:k-1]
        if head.startswith('@media') and 'prefers-color-scheme' in head: pass
        elif head.startswith('@media') and 'print' in head: pass
        elif head.startswith('@media'):
            inner=walk(body)
            if inner: res.append(head+'{'+''.join(inner)+'}')
        elif head.startswith('@'): pass
        else:
            c=conv([x for x in re.split(r';(?![^()]*\))',body) if x.strip()])
            if c and pre(head): res.append(pre(head)+'{'+';'.join(c)+'}')
        i=k
    return res
rules=[]
for f in ('styles.css','home.css','games.css','account.css'):
    TEXT_ONLY=True; rules+=walk(load(f))
TEXT_ONLY=False; rules+=walk(load('minimal.css'))
